function Pages({onOpen,notify}:{onOpen:()=>void;notify:(m:string)=>void}) { const [pages,setPages]=useState([{name:'Home',url:'/',status:'Published',home:true},{name:'About',url:'/about',status:'Published'},{name:'Services',url:'/services',status:'Published'},{name:'Portfolio',url:'/portfolio',status:'Draft'},{name:'Contact',url:'/contact',status:'Draft'}]); const [search,setSearch]=useState(''); const [active,setActive]=useState(''); const filtered=pages.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())); return <div className="resource-page"><div className="resource-toolbar"><div className="search-input"><Search size={16}/><input placeholder="Search pages" value={search} onChange={e=>setSearch(e.target.value)}/></div><button className="filter-button">All pages <ChevronDown size={14}/></button></div><div className="pages-table"><div className="pages-header"><span>Page</span><span>Status</span><span>Last updated</span><span></span></div>{filtered.map((p,index)=><div className="page-row" key={p.name}><div className="page-name"><span className="page-icon"><FileText size={16}/></span><div><b>{p.name}{p.home&&<small>Homepage</small>}</b><span>{p.url}</span></div></div><span className={`status-pill ${p.status==='Published'?'status-published':'status-draft'}`}><i></i>{p.status}</span><span className="date-cell">{index===0?'2 hours ago':index===1?'1 day ago':'Sep '+(12-index)+', 2026'}</span><div className="page-actions"><button onClick={onOpen}><Pencil size={15}/>Edit</button><button onClick={()=>setActive(active===p.name?'':p.name)}><MoreHorizontal size={18}/></button>{active===p.name&&<div className="row-pop"><button onClick={()=>notify('Page duplicated')}>Duplicate</button><button onClick={()=>{setPages(pages.filter(x=>x.name!==p.name));notify('Page moved to trash')}}>Delete</button></div>}</div></div>)}</div><button className="empty-add" onClick={()=>notify('New page created')}><Plus size={16}/>Create a page</button></div> }

