function Builder({onExit,notify}:{onExit:()=>void;notify:(m:string)=>void}) {
 const [tree,setTree]=useState<BuilderNode[]>(initialTree);const [selected,setSelected]=useState('heading');const [history,setHistory]=useState<BuilderNode[][]>([initialTree]);const [historyIndex,setHistoryIndex]=useState(0);const [clipboard,setClipboard]=useState<BuilderNode|null>(null);const [leftOpen,setLeftOpen]=useState(true);const [rightOpen,setRightOpen]=useState(true);const [navigatorOpen,setNavigatorOpen]=useState(false);const [device,setDevice]=useState<Device>('desktop');const [rightTab,setRightTab]=useState('Content');const [expanded,setExpanded]=useState<string[]>(['Basic','Layout']);const [saving,setSaving]=useState(false);const [preview,setPreview]=useState(false);const [globalOpen,setGlobalOpen]=useState(false);const [mediaOpen,setMediaOpen]=useState(false);
 const flatten=(nodes:BuilderNode[]):BuilderNode[]=>nodes.flatMap(n=>[n,...flatten(n.children||[])]); const selectedNode=flatten(tree).find(n=>n.id===selected);
 const updateTree=(nodes:BuilderNode[],id:string,updater:(n:BuilderNode)=>BuilderNode):BuilderNode[]=>nodes.map(n=>n.id===id?updater(n):{...n,children:n.children?updateTree(n.children,id,updater):undefined});
 const commit=(next:BuilderNode[])=>{const chopped=history.slice(0,historyIndex+1);const complete=[...chopped,next];setTree(next);setHistory(complete);setHistoryIndex(complete.length-1)}
 const undo=()=>{if(historyIndex>0){setHistoryIndex(historyIndex-1);setTree(history[historyIndex-1]);notify('Undo')}};const redo=()=>{if(historyIndex<history.length-1){setHistoryIndex(historyIndex+1);setTree(history[historyIndex+1]);notify('Redo')}};
 const makeNode=(type:ElementType,label:string):BuilderNode=>({id:shortId(),type,label,content:type==='heading'?'A new heading':type==='button'?'Get started →':type==='text'?'Write something meaningful here.':type==='image'?'https://images.unsplash.com/photo-1523726491678-bf852e717f6a?auto=format&fit=crop&w=800&q=80':type==='divider'?'':type==='spacer'?'':type==='video'?'Video placeholder':type==='faq'?'A common question, answered.':type==='pricing'?'A plan that fits.':type==='testimonials'?'“A thoughtful experience.”':'A new section',children:type==='container'||type==='columns'||type==='grid'?[]:undefined});
 const appendNode=(type:ElementType,label:string,target?:string)=>{const newNode=makeNode(type,label);if(target){commit(updateTree(tree,target,n=>({...n,children:[...(n.children||[]),newNode]})))}else commit([...tree,newNode]);setSelected(newNode.id);notify(`${label} added to canvas`)}
 const deleteNode=(id=selected)=>{if(!id)return;const remove=(nodes:BuilderNode[]):BuilderNode[]=>nodes.filter(n=>n.id!==id).map(n=>({...n,children:n.children?remove(n.children):undefined}));commit(remove(tree));setSelected('');notify('Element deleted')}
 const duplicate=()=>{if(!selectedNode)return;const clone={...selectedNode,id:shortId(),label:selectedNode.label+' copy'};commit([...tree,clone]);setSelected(clone.id);notify('Element duplicated')}
 const copy=()=>{if(selectedNode){setClipboard(selectedNode);notify('Element copied')}}; const paste=()=>{if(clipboard){const n={...clipboard,id:shortId(),label:clipboard.label+' copy'};commit([...tree,n]);setSelected(n.id);notify('Element pasted')}}
 const save=()=>{setSaving(true);window.setTimeout(()=>{setSaving(false);notify('All changes saved')},700)}
 useEffect(()=>{const key=(e:KeyboardEvent)=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();if(e.shiftKey)redo();else undo()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();save()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='c'){e.preventDefault();copy()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='v'){e.preventDefault();paste()}if(e.key==='Delete'||e.key==='Backspace'){const tgt=e.target as HTMLElement;if(tgt.tagName!=='INPUT'&&tgt.tagName!=='TEXTAREA'){deleteNode()}}if(e.key==='Escape')setSelected('')};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)})
 return <div className="builder-shell"><header className="builder-topbar"><div className="builder-project"><button className="exit-builder" onClick={onExit} title="Back to dashboard"><ChevronLeft size={17}/></button><Brand compact/><span></span><button>North Studio — Home <ChevronDown size={13}/></button></div><div className="builder-devices">{([['desktop',Monitor,'Desktop'],['tablet',Tablet,'Tablet'],['mobile',Smartphone,'Mobile']] as [Device,React.ElementType,string][]).map(([id,Icon,label])=><button key={id} onClick={()=>setDevice(id)} className={device===id?'active':''} title={label}><Icon size={16}/><span>{label}</span></button>)}</div><div className="builder-actions"><button onClick={undo} disabled={historyIndex===0} title="Undo (Ctrl+Z)"><Undo2 size={17}/></button><button onClick={redo} disabled={historyIndex===history.length-1} title="Redo (Ctrl+Shift+Z)"><Redo2 size={17}/></button><i></i><button onClick={()=>setPreview(true)} title="Preview"><Eye size={17}/><span>Preview</span></button><Button onClick={save} className="builder-save" icon={saving?<Loader2 className="spin" size={15}/>:<Save size={15}/>}>{saving?'Saving':'Save'}</Button><Button onClick={()=>notify('Website published successfully')} className="builder-publish" icon={<Rocket size={15}/>}>Publish</Button></div></header><div className="builder-body">{leftOpen?<aside className="elements-panel"><div className="panel-head"><div><Blocks size={16}/><b>Elements</b></div><button onClick={()=>setLeftOpen(false)} title="Collapse panel"><PanelLeftClose size={16}/></button></div><div className="element-search"><Search size={15}/><input placeholder="Search elements"/></div><div className="elements-list">{elementGroups.map(group=><div className="builder-group" key={group.title}><button className="builder-group-head" onClick={()=>setExpanded(expanded.includes(group.title)?expanded.filter(e=>e!==group.title):[...expanded,group.title])}><span>{group.title}</span><ChevronDown size={14} className={expanded.includes(group.title)?'':'rotated'}/></button>{expanded.includes(group.title)&&<div>{group.items.map(([type,name,description,Icon],i)=><div className="builder-element" draggable onDragStart={e=>e.dataTransfer.setData('speed-type',JSON.stringify({type,name}))} onClick={()=>appendNode(type,name)} key={name+i}><GripVertical size={14}/><span className="element-icon"><Icon size={15}/></span><div><b>{name}</b><small>{description}</small></div></div>)}</div>}</div>)}</div><div className="elements-bottom"><button onClick={()=>setNavigatorOpen(!navigatorOpen)}><Layers3 size={16}/>Navigator</button><button onClick={()=>setGlobalOpen(true)}><WandSparkles size={16}/>Global styles</button></div></aside>:<button className="collapsed-panel-button left" onClick={()=>setLeftOpen(true)}><PanelLeftOpen size={17}/></button>}<main className="builder-workspace"><div className="workspace-toolbar"><button onClick={()=>setNavigatorOpen(!navigatorOpen)} className={navigatorOpen?'tool-active':''}><Layers3 size={15}/>Layers</button><span>Page canvas</span><div><button title="Zoom out">−</button><b>{device==='desktop'?'100':'80'}%</b><button title="Zoom in">+</button></div></div><div className="workspace-scroll"><div className={`website-canvas ${device}`} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();try{const {type,name}=JSON.parse(e.dataTransfer.getData('speed-type'));appendNode(type,name)}catch{}}} onClick={()=>setSelected('')}><CanvasNodes nodes={tree} selected={selected} setSelected={setSelected} update={(id,content)=>commit(updateTree(tree,id,n=>({...n,content})))} /></div><div className="canvas-add" onClick={()=>appendNode('container','Section')}><Plus size={15}/>Add section</div></div></main>{rightOpen?<aside className="settings-panel"><div className="panel-head"><div><Settings2 size={16}/><b>{selectedNode?selectedNode.label:'Page settings'}</b></div><button onClick={()=>setRightOpen(false)} title="Collapse panel"><PanelRightClose size={16}/></button></div><div className="settings-tabs">{['Content','Style','Advanced'].map(t=><button className={rightTab===t?'active':''} onClick={()=>setRightTab(t)} key={t}>{t}</button>)}</div>{selectedNode?<SettingsContent node={selectedNode} tab={rightTab} update={content=>commit(updateTree(tree,selectedNode.id,n=>({...n,content})))} onMedia={()=>setMediaOpen(true)}/>:<div className="no-selection"><MousePointer2 size={22}/><b>Select an element</b><p>Choose something on the canvas to start editing it.</p></div>}</aside>:<button className="collapsed-panel-button right" onClick={()=>setRightOpen(true)}><PanelRightClose size={17}/></button>}</div>{selectedNode&&<FloatingToolbar node={selectedNode} onMove={()=>notify('Drag the element on canvas to move it')} onEdit={()=>setRightTab('Content')} onDuplicate={duplicate} onCopy={copy} onPaste={paste} onDelete={()=>deleteNode()}/>}<AnimatePresence>{navigatorOpen&&<Navigator tree={tree} selected={selected} select={id=>setSelected(id)} close={()=>setNavigatorOpen(false)}/>} {globalOpen&&<GlobalModal close={()=>setGlobalOpen(false)} notify={notify}/>} {mediaOpen&&<MediaModal close={()=>setMediaOpen(false)} select={url=>{commit(updateTree(tree,selectedNode?.id||'',n=>({...n,content:url})));setMediaOpen(false);notify('Image updated')}}/>} {preview&&<PreviewModal tree={tree} close={()=>setPreview(false)}/>}</AnimatePresence></div>
}

function CanvasNodes({nodes,selected,setSelected,update,depth=0}:{nodes:BuilderNode[];selected:string;setSelected:(id:string)=>void;update:(id:string,value:string)=>void;depth?:number}) {return <>{nodes.map(node=>{const isSelected=selected===node.id;const common={className:`canvas-node node-${node.type} ${isSelected?'is-selected':''}`,onClick:(e:React.MouseEvent)=>{e.stopPropagation();setSelected(node.id)}};if(node.type==='container'||node.type==='columns'||node.type==='grid')return <section {...common} key={node.id}><div className="node-label">{node.label}</div>{node.id==='nav'&&<div className="canvas-nav"><b>{node.children?.[0]?.content}</b><span>{node.children?.[1]?.content}</span><button>{node.children?.[2]?.content}</button></div>}{node.id==='hero'&&<><div className="canvas-hero"><div><small>{node.children?.[0]?.content}</small><h1 contentEditable suppressContentEditableWarning onBlur={e=>update('heading',e.currentTarget.textContent||'')}>{node.children?.[1]?.content}</h1><p contentEditable suppressContentEditableWarning onBlur={e=>update('hero-copy',e.currentTarget.textContent||'')}>{node.children?.[2]?.content}</p><button>{node.children?.[3]?.content}</button></div><img src={node.children?.[4]?.content} alt=""/></div></>}{node.id==='feature-section'&&<div className="canvas-feature"><small>OUR APPROACH</small><h2>{node.children?.[0]?.content}</h2><p>{node.children?.[1]?.content}</p><div><span>01<br/><b>Find the signal.</b></span><span>02<br/><b>Build the system.</b></span><span>03<br/><b>Move with intent.</b></span></div></div>}{node.id==='footer'&&<div className="canvas-footer"><b>{node.children?.[0]?.content}</b><span>{node.children?.[1]?.content}</span><i>Instagram&nbsp;&nbsp; LinkedIn&nbsp;&nbsp; Email</i></div>}{!['nav','hero','feature-section','footer'].includes(node.id)&&<div className="generic-container"><CanvasNodes nodes={node.children||[]} selected={selected} setSelected={setSelected} update={update} depth={depth+1}/>{node.children?.length===0&&<button onClick={(e)=>e.stopPropagation()}>Drop elements here</button>}</div>}</section>;
 if(node.type==='heading')return <h2 {...common} key={node.id} contentEditable suppressContentEditableWarning onBlur={e=>update(node.id,e.currentTarget.textContent||'')}>{node.content}</h2>;if(node.type==='text')return <p {...common} key={node.id} contentEditable suppressContentEditableWarning onBlur={e=>update(node.id,e.currentTarget.textContent||'')}>{node.content}</p>;if(node.type==='button')return <button {...common} key={node.id}>{node.content}</button>;if(node.type==='image')return <img {...common} key={node.id} src={node.content} alt=""/>;if(node.type==='divider')return <hr {...common} key={node.id}/>;if(node.type==='spacer')return <div {...common} key={node.id} style={{height:60}}/>;return <div {...common} key={node.id}>{node.content}</div>})}</>}

function FloatingToolbar({node,onMove,onEdit,onDuplicate,onCopy,onPaste,onDelete}:{node:BuilderNode;onMove:()=>void;onEdit:()=>void;onDuplicate:()=>void;onCopy:()=>void;onPaste:()=>void;onDelete:()=>void}){return <div className="floating-toolbar"><button onClick={onMove} title="Move"><Move size={15}/></button><button onClick={onEdit} title="Edit"><Pencil size={15}/></button><i></i><button onClick={onDuplicate} title="Duplicate"><Copy size={15}/></button><button onClick={onCopy} title="Copy"><Clipboard size={15}/></button><button onClick={onPaste} title="Paste"><Download size={15}/></button><i></i><button onClick={onDelete} className="delete-tool" title="Delete"><Trash2 size={15}/></button></div>}

function SettingsContent({node,tab,update,onMedia}:{node:BuilderNode;tab:string;update:(value:string)=>void;onMedia:()=>void}) { if(tab==='Content')return <div className="settings-content">{node.type==='heading'&&<><SettingsLabel label="Text"><textarea value={node.content} onChange={e=>update(e.target.value)}/></SettingsLabel><SettingsSelect label="HTML tag" value="H1"/><SettingsSegment label="Alignment"/></>}{node.type==='image'&&<><button className="image-upload" onClick={onMedia}><ImagePlus size={18}/><b>Choose image</b><span>Upload or select from library</span></button><SettingsLabel label="Image URL"><input value={node.content} onChange={e=>update(e.target.value)}/></SettingsLabel><SettingsLabel label="Alt text"><input placeholder="Describe this image"/></SettingsLabel><div className="settings-two"><SettingsSelect label="Width" value="Auto"/><SettingsSelect label="Object fit" value="Cover"/></div></>}{node.type==='button'&&<><SettingsLabel label="Text"><input value={node.content} onChange={e=>update(e.target.value)}/></SettingsLabel><SettingsLabel label="Link"><input placeholder="https://"/></SettingsLabel><SettingsSelect label="Icon" value="Arrow right"/><SettingsSegment label="Icon position"/><label className="toggle-line"><span>Open in new tab</span><i></i></label></>}{!['heading','image','button'].includes(node.type)&&<><SettingsLabel label={node.type==='text'?'Text':'Content'}><textarea value={node.content} onChange={e=>update(e.target.value)}/></SettingsLabel><SettingsSelect label="Element type" value={node.label}/><div className="hint-box"><Sparkles size={15}/><span>Tip: drag elements directly onto the canvas to build your layout.</span></div></>}</div>;
 if(tab==='Style')return <div className="settings-content style-content"><ResponsiveSwitch/><AccordionControl title="Typography" open><SettingsSelect label="Font family" value="Instrument Sans"/><div className="settings-two"><SettingsLabel label="Font size"><input value={node.type==='heading'?'72':'16'} readOnly/><small>px</small></SettingsLabel><SettingsSelect label="Weight" value={node.type==='heading'?'600':'400'}/></div><div className="settings-two"><SettingsLabel label="Line height"><input value="1.1" readOnly/></SettingsLabel><SettingsLabel label="Letter spacing"><input value="0" readOnly/><small>px</small></SettingsLabel></div><SettingsSegment label="Alignment"/></AccordionControl><AccordionControl title="Colors" open><div className="color-control"><span>Text color</span><button><i></i>#162033</button></div><div className="color-control"><span>Background</span><button><i className="transparent"></i>Transparent</button></div></AccordionControl><AccordionControl title="Spacing"><BoxModel/></AccordionControl><AccordionControl title="Border"><div className="settings-two"><SettingsLabel label="Width"><input value="0" readOnly/><small>px</small></SettingsLabel><SettingsSelect label="Style" value="Solid"/></div><div className="color-control"><span>Color</span><button><i className="transparent"></i>Transparent</button></div><SettingsLabel label="Radius"><input value="0" readOnly/><small>px</small></SettingsLabel></AccordionControl><AccordionControl title="Shadow"/></div>;
 return <div className="settings-content advanced-content"><ResponsiveSwitch/><SettingsLabel label="CSS ID"><input placeholder="e.g. hero-heading"/></SettingsLabel><SettingsLabel label="CSS classes"><input placeholder="Add classes"/></SettingsLabel><SettingsLabel label="Custom attributes"><textarea placeholder={'data-name="value"'}/></SettingsLabel><div className="hint-box"><Code2 size={15}/><span>Need precision? Add custom CSS in Global styles.</span></div></div> }
function SettingsLabel({label,children}:{label:string;children:React.ReactNode}){return <label className="setting-label"><span>{label}</span><div className="setting-input">{children}</div></label>};function SettingsSelect({label,value}:{label:string;value:string}){return <label className="setting-label"><span>{label}</span><button className="settings-select">{value}<ChevronDown size={14}/></button></label>};function SettingsSegment({label}:{label:string}){return <label className="setting-label"><span>{label}</span><div className="segment"><button className="selected">≡</button><button>☰</button><button>≣</button></div></label>};function AccordionControl({title,open=false,children}:{title:string;open?:boolean;children?:React.ReactNode}){const [isOpen,setIsOpen]=useState(open);return <div className="settings-accordion"><button onClick={()=>setIsOpen(!isOpen)}>{title}<ChevronDown size={15} className={isOpen?'':'rotated'}/></button>{isOpen&&<div>{children}</div>}</div>};function ResponsiveSwitch(){return <div className="responsive-switch"><span>Editing for</span><button className="active"><Monitor size={13}/>Desktop</button><button><Tablet size={13}/></button><button><Smartphone size={13}/></button></div>}; function BoxModel(){return <div className="box-model"><b>Margin</b><div><i>0</i><i>0</i><i>0</i><i>0</i><span>Padding</span><i>80</i><i>0</i><i>80</i><i>0</i></div></div>}

function Navigator({tree,selected,select,close}:{tree:BuilderNode[];selected:string;select:(id:string)=>void;close:()=>void}){const render=(nodes:BuilderNode[],level=0):React.ReactNode=>nodes.map(n=><React.Fragment key={n.id}><button className={selected===n.id?'selected':''} style={{paddingLeft:14+level*18}} onClick={()=>select(n.id)}>{n.children?.length?<ChevronDown size={13}/>:<span className="tree-space"></span>}<GripVertical size={13}/><span className={`tree-icon tree-${n.type}`}>{n.type==='heading'?<Heading1 size={13}/>:n.type==='image'?<Image size={13}/>:n.type==='button'?<SquareDashedMousePointer size={13}/>:n.type==='text'?<FileText size={13}/>:<Box size={13}/>}</span>{n.label}</button>{n.children&&render(n.children,level+1)}</React.Fragment>);return <motion.aside className="navigator-panel" initial={{x:-22,opacity:0}} animate={{x:0,opacity:1}} exit={{x:-22,opacity:0}}><div><b><Layers3 size={15}/>Navigator</b><button onClick={close}><X size={16}/></button></div><p>PAGE STRUCTURE</p>{render(tree)}</motion.aside>}
function GlobalModal({close,notify}:{close:()=>void;notify:(m:string)=>void}){return <motion.div className="modal-backdrop builder-modal" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onMouseDown={close}><motion.div className="global-modal" initial={{scale:.98,y:12}} animate={{scale:1,y:0}} exit={{scale:.98,y:12}} onMouseDown={e=>e.stopPropagation()}><div className="modal-top"><div><WandSparkles size={18}/><span><b>Global styles</b><small>North Studio design system</small></span></div><button onClick={close}><X size={18}/></button></div><div className="global-modal-content"><aside><button className="active"><div className="multi-color"></div>Colors</button><button><Bold size={16}/>Typography</button><button><Move size={16}/>Spacing</button></aside><main><span className="eyebrow plain">Brand foundation</span><h2>Global colors</h2><p>Changes you make here instantly flow through components using global styles.</p><div className="edit-colors">{[['Primary','#155EEF'],['Secondary','#142040'],['Accent','#93F2D2'],['Surface','#FFFFFF'],['Text','#162033'],['Muted','#667085']].map(([name,color])=><label key={name}><i style={{background:color}}></i><span>{name}</span><input value={color} readOnly/></label>)}</div></main></div><div className="modal-bottom"><button onClick={close}>Cancel</button><Button onClick={()=>{notify('Global styles updated');close()}}>Save styles</Button></div></motion.div></motion.div>}
function MediaModal({close,select}:{close:()=>void;select:(url:string)=>void}){const imgs=['https://images.unsplash.com/photo-1519608487953-e999c86e7450?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1531058020387-3be344556be6?auto=format&fit=crop&w=800&q=80'];return <motion.div className="modal-backdrop builder-modal" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onMouseDown={close}><motion.div className="media-modal" initial={{scale:.98,y:12}} animate={{scale:1,y:0}} exit={{scale:.98,y:12}} onMouseDown={e=>e.stopPropagation()}><div className="modal-top"><div><Image size={18}/><span><b>Media library</b><small>Select an image for this element</small></span></div><button onClick={close}><X size={18}/></button></div><div className="media-modal-head"><div className="search-input"><Search size={15}/><input placeholder="Search media"/></div><Button variant="secondary"><Upload size={14}/>Upload</Button></div><div className="media-modal-grid">{imgs.map((src,i)=><button key={src} onClick={()=>select(src)}><img src={src} alt=""/><span>{['Northern lights','Studio desk','Bright workspace','Color geometry'][i]}</span></button>)}</div></motion.div></motion.div>}
function PreviewModal({tree,close}:{tree:BuilderNode[];close:()=>void}){return <motion.div className="preview-overlay" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}><div className="preview-overlay-top"><Brand compact/><span>Previewing: North Studio — Home</span><button onClick={close}><X size={17}/>Exit preview</button></div><div className="live-preview"><CanvasNodes nodes={tree} selected="" setSelected={()=>{}} update={()=>{}}/></div></motion.div>}

createRoot(document.getElementById('root')!).render(<App />)
